function jsonShape(value) {
  if (value === null) return 'JSON이 아닌 응답 본문';
  if (Array.isArray(value)) {
    const item = value[0];
    return item && typeof item === 'object' ? `객체 배열(${Object.keys(item).join(', ')})` : '배열';
  }
  if (typeof value === 'object') return `객체(${Object.keys(value).join(', ')})`;
  return typeof value;
}

function exampleExplanation(item, sample, index) {
  const request = sample.input;
  const details = ['query', 'headers', 'json']
    .filter((key) => request[key] !== undefined)
    .map((key) => `${key}=${JSON.stringify(request[key])}`)
    .join(', ');
  const response = sample.expected.json === null
    ? '본문은 JSON 형식이 아닙니다.'
    : `JSON ${JSON.stringify(sample.expected.json)}`;
  return `${item.explanation} 사례 ${index + 1}: ${request.method} ${request.path}${details ? ` (${details})` : ''} → HTTP ${sample.expected.status}, ${response}`;
}

function acceptanceRequirements(item) {
  const cases = item.cases;
  const routes = [...new Set(cases.map(({ input }) => `${input.method} ${input.path}`))];
  const statuses = [...new Set(cases.map(({ expected }) => expected.status))].sort((left, right) => left - right);
  const shapes = [...new Set(cases.map(({ expected }) => jsonShape(expected.json)))];
  return [
    item.objective,
    `대상 요청: ${routes.join(' · ')}.`,
    `허용할 HTTP 상태 코드: ${statuses.join(', ')}.`,
    `응답 모양: ${shapes.join(' 또는 ')}. 각 공개 사례의 요청 값에 맞춰 결과를 만듭니다.`,
  ];
}

function sourcesFor(topic) {
  return [
    reference,
    releaseReference,
    ...topicReferences[topic].map((source) => ({ ...source, reviewedAt: '2026-10-16' })),
  ];
}

const responseCase = (method, path, json, { query, headers, body, status = 200 } = {}) => {
  const input = { method, path };
  if (query !== undefined) input.query = query;
  if (headers !== undefined) input.headers = headers;
  if (body !== undefined) input.json = body;
  return { input, expected: { status, json } };
};

const getQueryCases = (path, key, values, expected, options = {}) => values.map((value) => {
  const query = value === undefined ? undefined : { [key]: value };
  return responseCase('GET', path, expected(value), { ...options, query });
});

const getPathCases = (pathFor, values, expected, options = {}) => values.map((value) =>
  responseCase('GET', pathFor(value), expected(value), options));

const postCases = (path, values, expected, { method = 'POST', status = 200 } = {}) => values.map((body, index) =>
  responseCase(method, path, expected(body, index), { body, status }));

