    objective: '응답 모델이 외부 공개 응답의 필드를 제한합니다.',
    statement: '`GET /learners/{learner_id}` 응답에 id와 name만 포함하세요. 내부 객체의 email과 access_token은 응답에 포함되면 안 됩니다.',
    starter: 'from fastapi import FastAPI\n\napp = FastAPI()\n\n@app.get("/learners/{learner_id}")\nasync def read_learner(learner_id: int):\n    return {"id": learner_id, "name": "Mina", "email": "private@example.test", "access_token": "secret"}',
    solution: 'from fastapi import FastAPI\nfrom pydantic import BaseModel\n\napp = FastAPI()\n\nclass LearnerPublic(BaseModel):\n    id: int\n    name: str\n\n@app.get("/learners/{learner_id}", response_model=LearnerPublic)\nasync def read_learner(learner_id: int):\n    return {"id": learner_id, "name": f"Learner {learner_id}", "email": "private@example.test", "access_token": "secret"}',
