    starter: 'from fastapi import FastAPI\nfrom pydantic import BaseModel\n\napp = FastAPI()\nclass ProfileCreate(BaseModel):\n    name: str\n\n@app.post("/profiles")\nasync def create_profile(profile: ProfileCreate):\n    return {"name": profile.name}',
