    statement: '모든 요청에 미들웨어를 적용하세요. `GET /context` 응답은 요청의 method와 URL path를 반환해야 합니다.',
    starter: 'from fastapi import FastAPI, Request\n\napp = FastAPI()\n\n@app.get("/context")\nasync def context(request: Request):\n    return {"method": "", "path": ""}',
    solution: 'from fastapi import FastAPI, Request\n\napp = FastAPI()\n\n@app.middleware("http")\nasync def capture_request(request: Request, call_next):\n    request.state.method = request.method\n    request.state.path = request.url.path\n    return await call_next(request)\n\n@app.get("/context")\nasync def context(request: Request):\n    return {"method": request.state.method, "path": request.state.path}',
